"""
Reproduction script for the classmethod mocking bug.
"""

import pytest
from oop_ext.interface import Interface, ImplementsInterface, AssertImplements


def test_requires_declaration_bug():
    """Test that reproduces the bug with mocked classmethod."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # This should work without any mocking
    print("Testing without mocking...")
    AssertImplements(FooImplementation, IFoo, requires_declaration=True)
    print("✓ Works without mocking")

    # Now let's simulate the mocking scenario more accurately
    print("\nSimulating the mocking scenario...")
    try:
        # Import mock to create a MagicMock object similar to what mocker.spy would create
        from unittest.mock import MagicMock

        # Replace the method with a MagicMock (simulating what mocker.spy does)
        # The key difference is that we need to make sure the MagicMock is NOT recognized as a method
        original_foo = FooImplementation.foo
        mock_foo = MagicMock()
        FooImplementation.foo = mock_foo

        # This should fail with the current implementation
        AssertImplements(FooImplementation, IFoo, requires_declaration=True)
        print("✓ Works with mocking (bug is fixed)")

        # Restore the original method
        FooImplementation.foo = original_foo

    except AssertionError as e:
        print(f"✗ Failed with mocking (this is the bug): {e}")
        # Restore the original method for cleanup
        FooImplementation.foo = original_foo
        return True  # Bug reproduced

    return False  # Bug not reproduced


def test_with_actual_spy():
    """Test using actual pytest-mock spy functionality."""
